import { Box, Grid, Typography } from '@mui/material';
import WhatsAppCTAButton from '../../atoms/WhatsAppCTAButton';
import { useTranslation } from 'react-i18next';
import heroImage from '../../../assets/images/byteCodeScrum.jpg';
import LogoByteCode from '../../../assets/images/byteCode_Logo.svg';
import CodeCircle from '../../../assets/images/CodeCircle.svg';
import MyIcon from '../../../assets/images/icon_arrow-up-right.svg';
import { useInView } from 'react-intersection-observer';
import TextScramble from '../../atoms/TextScramble';

const HeroSection = () => {
  const { t } = useTranslation();

  const { ref, inView } = useInView({
    triggerOnce: true,
    threshold: 0.2,
  });

  const handleWhatsAppCTA = () => {
    const message = encodeURIComponent(
      `¡Hola ByteCode! 👋 Me interesa conocer más sobre sus servicios de desarrollo web y aplicaciones móviles. ¿Podrían ayudarme?`
    );
    const whatsappUrl = `https://wa.me/50232581367?text=${message}`;
    window.open(whatsappUrl, '_blank');
  };

  return (
    <Grid container sx={{ padding: 0 }}>
      <Grid
        container
        sx={{
          marginTop: 8,
          display: 'flex',
          flexDirection: 'column',
          alignItems: 'center',
          textAlign: 'center',
          py: 5,
        }}
      >
        {/* Content Section */}
        <Grid item xs={12} sx={{ mb: 4, mt: 4 }}>
          <Typography
            variant="h2"
            sx={{
              fontWeight: 'medium',
              fontSize: { xs: '2rem', md: '3rem', lg: '4rem' },
            }}
          >
            {t('heroSection.hero_title_1')}
            <Box
              sx={{
                display: 'inline-block',
                ml: 1,
                width: { xs: '30px', md: '45px' },
                height: { xs: '30px', md: '45px' },
              }}
            >
              <img
                src={CodeCircle}
                alt="Code Circle"
                style={{ width: '100%', height: '100%' }}
              />
            </Box>
          </Typography>
          <Typography
            component="span"
            variant="h2"
            sx={{
              fontWeight: 'medium',
              mb: 2,
              fontSize: { xs: '2rem', md: '3rem', lg: '4rem' },
            }}
          >
            <TextScramble
              texts={[
                t('heroSection.hero_title_2_variant1'),
                t('heroSection.hero_title_2_variant2'),
                t('heroSection.hero_title_2_variant3'),
              ]}
              speed={200}
              pause={2000}
              //style={{ color: '#00DA94' }}
            />
          </Typography>

          <Typography variant="h6" sx={{ mb: 4 }}>
            {t('heroSection.hero_subtitle')}
          </Typography>
          <WhatsAppCTAButton onClick={handleWhatsAppCTA} icon={MyIcon}>
            {t('heroSection.hero_cta', 'Quiero que me contacten')}
          </WhatsAppCTAButton>
          <Box
            ref={ref}
            sx={{
              opacity: inView ? 1 : 0,
              transform: inView ? 'translateY(0)' : 'translateY(40px)',
              transition: 'all 0.9s cubic-bezier(0.22, 1, 0.36, 1)',
              willChange: 'opacity, transform',
            }}
          >
            <img
              src={heroImage}
              alt="Hero"
              style={{
                width: '90%',
                height: 'auto',
                borderRadius: '40px',
                marginLeft: '20px',
                marginRight: '20px',
                boxShadow: '0 8px 32px rgba(0,0,0,0.12)',
              }}
            />
          </Box>
        </Grid>
      </Grid>
    </Grid>
  );
};

export default HeroSection;
