import Grid from '@mui/material/Grid';
import Typography from '@mui/material/Typography';
import WhatsAppCTAButton from '../../atoms/WhatsAppCTAButton';
import Box from '@mui/material/Box';
import { useTranslation } from 'react-i18next';
import CodeSectionPhoto from '../../../assets/images/CodeSection.jpg';
import MyIcon from '../../../assets/images/icon_arrow-up-right.svg';
import { useInView } from 'react-intersection-observer';

const NewSection = () => {
  const { t } = useTranslation();

  const { ref, inView } = useInView({
    triggerOnce: true,
    threshold: 0.2,
  });

  const handleWhatsAppCTA = () => {
    const message = encodeURIComponent(
      `¡Hola ByteCode! 👋 Me interesa conocer más sobre sus servicios de desarrollo web y aplicaciones móviles. ¿Podrían ayudarme?`
    );
    const whatsappUrl = `https://wa.me/50232581367?text=${message}`;
    window.open(whatsappUrl, '_blank');
  };

  return (
    <Box
      sx={{
        backgroundColor: 'white',
        padding: '60px 0',
      }}
    >
      <Grid
        container
        spacing={2}
        sx={{ padding: '10px 20px', alignItems: 'center' }}
      >
        <Grid item xs={12} md={6}>
          <Box
            ref={ref}
            component="img"
            src={CodeSectionPhoto}
            alt="Texto en un editor de código"
            sx={{
              width: '90%',
              height: 'auto',
              borderRadius: '24px',
              opacity: inView ? 1 : 0,
              transform: inView ? 'translateX(0)' : 'translateX(40px)',
              transition: 'all 0.9s cubic-bezier(0.22, 1, 0.36, 1)',
              boxShadow: '0 8px 32px rgba(0,0,0,0.12)',
              willChange: 'opacity, transform',
            }}
          />
        </Grid>

        <Grid item xs={12} md={6} sx={{ padding: '0px 50px 0px 50px' }}>
          <Typography
            variant="h4"
            fontFamily="Aeonik"
            fontWeight="bold"
            color="#010101"
          >
            {t('codeSection.code_title')}
          </Typography>
          <Typography
            variant="body1"
            fontFamily="Aeonik"
            color="#010101"
            mt={2}
            mb={4}
          >
            {t('codeSection.code_description')}
          </Typography>
          <WhatsAppCTAButton onClick={handleWhatsAppCTA} icon={MyIcon}>
            {t('heroSection.hero_cta', 'Quiero que me contacten')}
          </WhatsAppCTAButton>
        </Grid>
      </Grid>
    </Box>
  );
};

export default NewSection;
