import React, { useState } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  CardMedia,
  Chip,
  Grid,
  IconButton,
  Link,
  useMediaQuery,
  useTheme,
} from '@mui/material';
import { ArrowBackIos, ArrowForwardIos } from '@mui/icons-material';
import recoWebAppImage from '../../../assets/images/reco_desktop.jpg';
import recoAppImage from '../../../assets/images/RecoApp.jpg';
import cometasImage from '../../../assets/images/CometasWebsite.jpg';
import RecoApiImage from '../../../assets/images/RecoRestAPI.jpg';
import { useTranslation } from 'react-i18next';

const OurProjectsSection = () => {
  const { t } = useTranslation();
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));

  const projects = [
    {
      title: t('ourProjects.projects.reco_web.title'),
      tags: [
        t('ourProjects.projects.reco_web.tags.web_app'),
        t('ourProjects.projects.reco_web.tags.seo'),
        t('ourProjects.projects.reco_web.tags.ux_ui'),
      ],
      image: recoWebAppImage,
      link: 'https://recolatam.com/',
      description: t('ourProjects.projects.reco_web.description'),
    },
    {
      title: t('ourProjects.projects.cometas.title'),
      tags: [
        t('ourProjects.projects.cometas.tags.website'),
        t('ourProjects.projects.cometas.tags.children'),
        t('ourProjects.projects.cometas.tags.pricing'),
      ],
      image: cometasImage,
      link: 'https://cometasclub.com/',
      description: t('ourProjects.projects.cometas.description'),
    },
    {
      title: t('ourProjects.projects.reco_app.title'),
      tags: [
        t('ourProjects.projects.reco_app.tags.mobile_app'),
        t('ourProjects.projects.reco_app.tags.android'),
        t('ourProjects.projects.reco_app.tags.ios'),
      ],
      image: recoAppImage,
      link: 'https://recolatam.com/',
      description: t('ourProjects.projects.reco_app.description'),
    },
    {
      title: t('ourProjects.projects.reco_api.title'),
      tags: [
        t('ourProjects.projects.reco_api.tags.rest_api'),
        t('ourProjects.projects.reco_api.tags.postman'),
        t('ourProjects.projects.reco_api.tags.database'),
      ],
      image: RecoApiImage,
      link: 'https://dev.recolatam.com/api-docs/',
      description: t('ourProjects.projects.reco_api.description'),
    },
  ];

  const [currentIndex, setCurrentIndex] = useState(0);
  const [isTransitioning, setIsTransitioning] = useState(false);
  const visibleSlides = isMobile ? 1 : 3;

  const handleNext = () => {
    if (isTransitioning) return; // Prevenir clicks múltiples durante la transición

    setIsTransitioning(true);
    setCurrentIndex(prevIndex =>
      prevIndex + visibleSlides >= projects.length ? 0 : prevIndex + 1
    );
    // Reset del estado de transición después de la animación
    setTimeout(() => setIsTransitioning(false), 500);
  };

  const handlePrev = () => {
    if (isTransitioning) return; // Prevenir clicks múltiples durante la transición

    setIsTransitioning(true);
    setCurrentIndex(prevIndex =>
      prevIndex === 0 ? projects.length - visibleSlides : prevIndex - 1
    );

    // Reset del estado de transición después de la animación
    setTimeout(() => setIsTransitioning(false), 500);
  };

  const slideWidth = 100 / visibleSlides;

  return (
    <Box
      sx={{
        backgroundColor: 'white',
        padding: { xs: '50px 20px', md: '88px 50px' },
      }}
    >
      <Grid container spacing={2}>
        <Grid item xs={12} sx={{ textAlign: 'center', marginBottom: '20px' }}>
          <Typography
            variant="h3"
            fontFamily="Aeonik"
            fontWeight="bold"
            color="#010101"
            gutterBottom
          >
            {t('ourProjects.ourProjects_title')}
          </Typography>
          <Typography variant="body1" fontFamily="Aeonik" color="#555555">
            {t('ourProjects.ourProjects_description')}
          </Typography>
        </Grid>

        {/* Project Carousel */}
        <Grid container justifyContent="center" alignItems="center">
          <Grid item xs={1} textAlign="center">
            <IconButton
              onClick={handlePrev}
              sx={{
                backgroundColor: '#f5f5f5',
                '&:hover': {
                  backgroundColor: '#010101',
                  color: 'white',
                  transform: 'scale(1.1)',
                },
                transition: 'all 0.3s ease',
                width: { xs: '40px', md: '50px' },
                height: { xs: '40px', md: '50px' },
              }}
            >
              <ArrowBackIos sx={{ fontSize: { xs: '16px', md: '20px' } }} />
            </IconButton>
          </Grid>

          <Grid item xs={10}>
            <Grid container spacing={2} justifyContent="center">
              {projects
                .slice(currentIndex, currentIndex + visibleSlides)
                .map((project, index) => (
                  <Grid item key={index} xs={12} sm={6} md={4}>
                    <Link href={project.link} target="_blank" underline="none">
                      <Card
                        sx={{
                          maxWidth: 345,
                          height: 'auto',
                          transition: 'all 0.4s cubic-bezier(0.4, 0.0, 0.2, 1)',
                          backgroundColor: 'transparent',
                          boxShadow: 'none',
                          cursor: 'pointer',
                          '&:hover': {
                            transform: 'translateY(-8px) scale(1.02)',
                            '& .project-image': {
                              transform: 'scale(1.05)',
                              filter: 'brightness(1.1)',
                            },
                            '& .project-title': {
                              color: '#010101',
                            },
                            '& .project-description': {
                              color: '#333',
                            },
                          },
                        }}
                      >
                        <CardContent>
                          <Typography
                            variant="h5"
                            fontFamily="Aeonik"
                            fontWeight="bold"
                            textAlign="center"
                          >
                            {project.title}
                          </Typography>

                          {project.description && (
                            <Typography
                              variant="body2"
                              fontFamily="Aeonik"
                              textAlign="center"
                              marginTop="10px"
                            >
                              {project.description}
                            </Typography>
                          )}
                        </CardContent>
                        <CardMedia
                          component="img"
                          height="300"
                          width="auto"
                          image={project.image}
                          alt={`Image of ${project.title}`}
                          sx={{
                            objectFit: 'cover',
                            borderRadius: '16px',
                          }}
                        />
                      </Card>
                      <Box
                        sx={{
                          display: 'flex',
                          gap: '10px',
                          justifyContent: 'left',
                          marginTop: '16px',
                        }}
                      >
                        {project.tags.map((tag, idx) => (
                          <Chip
                            key={idx}
                            label={tag}
                            sx={{
                              height: '28px',
                              fontSize: '0.75rem',
                              fontWeight: '500',
                              backgroundColor: '#010101',
                              color: '#fff',
                              border: '1px solid transparent',
                              transition: 'all 0.3s ease',
                              '&:hover': {
                                backgroundColor: 'transparent',
                                color: '#010101',
                                border: '1px solid #010101',
                                transform: 'translateY(-2px)',
                              },
                            }}
                          />
                        ))}
                      </Box>
                    </Link>
                  </Grid>
                ))}
            </Grid>
          </Grid>

          <Grid item xs={1} textAlign="center">
            <IconButton
              onClick={handleNext}
              sx={{
                backgroundColor: '#f5f5f5',
                '&:hover': {
                  backgroundColor: '#010101',
                  color: 'white',
                  transform: 'scale(1.1)',
                },
                transition: 'all 0.3s ease',
                width: { xs: '40px', md: '50px' },
                height: { xs: '40px', md: '50px' },
              }}
            >
              <ArrowForwardIos sx={{ fontSize: { xs: '16px', md: '20px' } }} />
            </IconButton>
          </Grid>
        </Grid>
      </Grid>
    </Box>
  );
};

export default OurProjectsSection;
